import 'dart:collection';

import 'package:voyager/domain/services/character_operation.dart';
import 'package:voyager/domain/services/fractional_index.dart';

/// Tracks in-memory character ops for an actively edited text field.
class CharacterOpSession {
  CharacterOpSession({
    required this.clientId,
    String? initialText,
    List<CharacterOperation>? initialOperations,

    /// When true, ops generated by seeding from [initialText] are added to
    /// [_pendingOpIds] so they will be uploaded as the initial CRDT chain for
    /// a brand-new document that has no remote ops yet.
    ///
    /// Keep this false (the default) when creating a session purely to
    /// reconstruct local state â€” e.g. from a race path where the user typed
    /// before [prepareEditingSession] finished loading the real remote chain.
    /// In that case only the actual edit delta should be uploaded, not a fresh
    /// copy of every existing character, which would collide with the positions
    /// already present in Firestore from the original authoring session.
    bool seedAsPending = false,
  }) : _logicalClock = 0 {
    if (initialOperations != null) {
      _loadFromOperations(initialOperations);
    } else if (initialText != null) {
      _seedFromText(
        initialText,
        markAsPending: seedAsPending,
        sharedIds: seedAsPending,
      );
    }
  }

  final String clientId;
  int _logicalClock;

  /// The run of characters this session is typing: the key its first
  /// character took, the suffix the last one added to it, and that last
  /// character's id. See [_positionFor].
  String? _runRoot;
  String? _runSuffix;
  String? _runLastId;

  /// The document order, the one [CharacterSequenceCrdtMerger.applyMergedText]
  /// spells text in: position, then logical clock, then client. Sorting by
  /// position alone left characters two devices had put at the same position
  /// in map order here, so this device saved and uploaded an order the other
  /// device's resolver never produced (BUG-235).
  static int compareOps(CharacterOperation a, CharacterOperation b) {
    final pos = a.position.compareTo(b.position);
    if (pos != 0) return pos;
    final clock = a.logicalClock.compareTo(b.logicalClock);
    if (clock != 0) return clock;
    return a.clientId.compareTo(b.clientId);
  }

  final Map<String, CharacterOperation> _opsById = {};
  final List<String> _pendingOpIds = [];

  List<CharacterOperation> get allOps =>
      _opsById.values.toList(growable: false);

  String get text => _reconstructText();

  /// The live operations in document order, and the text they spell.
  ///
  /// Cached because [recordTextChange] runs on every keystroke, and rebuilding
  /// the order means sorting every character by a position string that grows
  /// with the document â€” 15ms a keystroke at 8k characters, 200ms at 20k.
  /// [recordTextChange] keeps both up to date itself; everything else that
  /// changes [_opsById] wholesale clears them.
  List<CharacterOperation>? _live;
  String? _liveText;

  void resetFromText(String text) {
    _opsById.clear();
    _pendingOpIds.clear();
    _logicalClock = 0;
    _runLastId = null;
    _seedFromText(text, markAsPending: true);
    _editedSinceSeed = false;
  }

  /// Whether [recordTextChange] has recorded an edit since the session was
  /// seeded or last reset.
  bool _editedSinceSeed = false;

  /// Whether what is pending is only the seed the session was opened with:
  /// a copy of the stored text, not an edit made here (BUG-220).
  bool get onlySeedPending => hasPendingOps && !_editedSinceSeed;

  void recordTextChange(String before, String after) {
    if (before == after) return;
    _recordTextChange(before, after);
    _editedSinceSeed = true;
  }

  void _recordTextChange(String before, String after) {
    final live = _liveOrderedOps();
    // When the session already spells `before`, the edit below leaves it
    // spelling exactly `after`, so the rebuild the final check would do can be
    // skipped. Length too: the diff indexes ops by UTF-16 offset.
    final inSync = live.length == before.length && _reconstructText() == before;
    final oldText = before;

    // Simple diff: walk both strings.
    var i = 0;
    var j = 0;
    while (i < oldText.length && j < after.length && oldText[i] == after[j]) {
      i++;
      j++;
    }

    var oldEnd = oldText.length;
    var newEnd = after.length;
    while (oldEnd > i &&
        newEnd > j &&
        oldText[oldEnd - 1] == after[newEnd - 1]) {
      oldEnd--;
      newEnd--;
    }

    final deleteCount = oldEnd - i;
    final insertSegment = after.substring(j, newEnd);

    if (deleteCount > 0 && i < live.length) {
      final end = i + deleteCount < live.length ? i + deleteCount : live.length;
      for (final op in live.sublist(i, end)) {
        _tombstone(op.id);
      }
      live.removeRange(i, end);
    }

    if (insertSegment.isNotEmpty) {
      String? posBefore;
      String? posAfter;
      if (i > 0 && i - 1 < live.length) {
        posBefore = live[i - 1].position;
      }
      if (i < live.length) {
        posAfter = live[i].position;
        var nextIdx = i + 1;
        while (posAfter == posBefore && nextIdx < live.length) {
          posAfter = live[nextIdx].position;
          nextIdx++;
        }
        if (posAfter == posBefore) {
          posAfter = null;
        }
      }

      var cursorBefore = posBefore;
      final inserted = <CharacterOperation>[];
      final continuesRun = i > 0 && i - 1 < live.length
          ? live[i - 1].id == _runLastId
          : false;
      for (var k = 0; k < insertSegment.length; k++) {
        final char = insertSegment[k];
        final pos = _positionFor(
          before: cursorBefore,
          after: posAfter,
          continuesRun: continuesRun || k > 0,
        );
        final op = _insertOp(char: char, position: pos);
        inserted.add(op);
        _runLastId = op.id;
        cursorBefore = pos;
      }

      // Spliced in at the diff index, which is where a sort would put them as
      // long as they sort strictly between their new neighbours. When they
      // don't â€” equal positions skipped above, or a desynced index â€” the
      // cached order is dropped and the next read sorts from scratch.
      if (i <= live.length) {
        live.insertAll(i, inserted);
        final next = i + inserted.length;
        if ((i > 0 && compareOps(live[i - 1], inserted.first) >= 0) ||
            (next < live.length &&
                compareOps(inserted.last, live[next]) >= 0)) {
          _live = null;
        }
      } else {
        _live = null;
      }
    }

    _liveText = inSync && _live != null ? after : null;

    // If diff produced no ops but text changed structurally, re-seed.
    if (_reconstructText() != after) {
      resetFromText(after);
    }
  }

  /// The key for a character typed between [before] and [after].
  ///
  /// Two devices typing at the same place see the same neighbours, and keys
  /// minted from the neighbours alone came out the same on both, character for
  /// character: the two words then sorted letter by letter into each other
  /// (BUG-235). So a run of typing starts at a key carrying this client's own
  /// digits, and each character typed straight after the last one extends that
  /// key rather than stepping past it: every key of the run sorts before any
  /// key another device's run at the same place can take, or after all of
  /// them, and the run stays whole.
  String _positionFor({
    String? before,
    String? after,
    required bool continuesRun,
  }) {
    final root = _runRoot;
    if (continuesRun && root != null) {
      final suffix = _runSuffix == null
          ? FractionalIndex.first()
          : FractionalIndex.after(_runSuffix!);
      final key = '$root$suffix';
      if (after == null || key.compareTo(after) < 0) {
        _runSuffix = suffix;
        return key;
      }
    }
    final base = FractionalIndex.between(before: before, after: after);
    var start = '$base$_clientDigits';
    // [base] can be a prefix of [after], and its extension then past it.
    if (after != null && start.compareTo(after) >= 0) {
      start = FractionalIndex.between(before: base, after: after);
    }
    _runRoot = start;
    _runSuffix = null;
    return start;
  }

  /// Two digits from [clientId], never '0' (a key may not end in one), that
  /// set this client's runs apart from another's at the same place.
  late final String _clientDigits = () {
    var hash = 0x811c9dc5;
    for (final unit in clientId.codeUnits) {
      hash = ((hash ^ unit) * 0x01000193) & 0xffffffff;
    }
    const digits =
        '123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
    return '${digits[hash % 61]}${digits[(hash ~/ 61) % 61]}';
  }();

  List<CharacterOperation> takePendingOps() {
    final pending = _pendingOpIds
        .map((id) => _opsById[id])
        .whereType<CharacterOperation>()
        .toList();
    _pendingOpIds.clear();
    return pending;
  }

  /// Puts operations from a failed upload back in the pending set.
  ///
  /// [takePendingOps] clears unconditionally, so an upload that then throws
  /// used to lose those operations for good: they stay in [_opsById], which
  /// means [text] already accounts for them and no later [recordTextChange]
  /// will ever emit them again. The paragraph typed offline would simply never
  /// reach `sync_operations`, and any device resolving the document from the
  /// log would render it missing.
  ///
  /// Restored at the front, because the user may have kept typing while the
  /// upload was in flight and those newer operations must still follow these.
  /// Ids already pending are left alone rather than duplicated â€” an operation
  /// tombstoned after it was taken is back in the list under its own id.
  void restorePendingOps(List<CharacterOperation> operations) {
    if (operations.isEmpty) return;
    final alreadyPending = _pendingOpIds.toSet();
    final restored = [
      for (final op in operations)
        if (_opsById.containsKey(op.id) && alreadyPending.add(op.id)) op.id,
    ];
    if (restored.isEmpty) return;
    _pendingOpIds.insertAll(0, restored);
  }

  /// Whether this session holds operations no upload has taken yet.
  bool get hasPendingOps => _pendingOpIds.isNotEmpty;

  /// Folds operations read back from the shared log into this session.
  ///
  /// A session is loaded once, when its document opens, and nothing used to
  /// tell it about operations another device wrote after that. Text from those
  /// operations still reached the editor â€” a pull re-seeding an idle editor, a
  /// buffered merge injected into a focused one â€” and was then diffed against a
  /// session that had never seen it, so it went back up as this device's own
  /// characters at the very fractional positions the other device had already
  /// used: every character twice on the next merge.
  ///
  /// Same winner rule as [CharacterSequenceCrdtMerger]: a tombstone beats a
  /// live copy, then the higher logical clock, then the higher client id.
  /// Pending operations stay pending.
  void absorbRemote(List<CharacterOperation> operations) {
    var changed = false;
    for (final op in operations) {
      final existing = _opsById[op.id];
      if (existing != null && !_remoteWins(op, existing)) continue;
      _opsById[op.id] = op;
      changed = true;
      if (op.clientId == clientId && op.logicalClock >= _logicalClock) {
        _logicalClock = op.logicalClock + 1;
      }
    }
    if (!changed) return;
    _live = null;
    _liveText = null;
  }

  bool _remoteWins(CharacterOperation incoming, CharacterOperation existing) {
    if (incoming.deleted != existing.deleted) return incoming.deleted;
    if (incoming.logicalClock != existing.logicalClock) {
      return incoming.logicalClock > existing.logicalClock;
    }
    return incoming.clientId.compareTo(existing.clientId) > 0;
  }

  /// The live characters in document order: a view of the session's own
  /// list, not a copy, so it holds only until the session next changes.
  List<CharacterOperation> get liveOps =>
      UnmodifiableListView(_liveOrderedOps());

  /// The text offset just after [op]. Found by id among the characters that
  /// share its position, since another device can mint the same one. Deleted
  /// since, it is where [op] stood: before every character at its position.
  int offsetAfter(CharacterOperation op) {
    final live = _liveOrderedOps();
    var low = 0;
    var high = live.length;
    while (low < high) {
      final mid = (low + high) >> 1;
      if (live[mid].position.compareTo(op.position) < 0) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    for (var i = low; i < live.length; i++) {
      if (live[i].position != op.position) break;
      if (live[i].id == op.id) return i + 1;
    }
    return low;
  }

  /// The live operations [recordTextChange] would tombstone going from [text]
  /// to [after], without recording anything.
  List<CharacterOperation> opsReplacedBy(String after) {
    final live = _liveOrderedOps();
    final before = _reconstructText();
    var i = 0;
    while (i < before.length && i < after.length && before[i] == after[i]) {
      i++;
    }
    var oldEnd = before.length;
    var newEnd = after.length;
    while (oldEnd > i &&
        newEnd > i &&
        before[oldEnd - 1] == after[newEnd - 1]) {
      oldEnd--;
      newEnd--;
    }
    if (oldEnd <= i || i >= live.length) return const [];
    return live.sublist(i, oldEnd < live.length ? oldEnd : live.length);
  }

  /// With [sharedIds], each character's id comes from the text and its
  /// position, not this client: the seed that starts a document's log.
  /// Two devices that open the same text before either's log arrives both
  /// seed it, and ids of their own made two copies of every character that
  /// the merge kept side by side (BUG-235). The same text now gives the same
  /// ids, so the copies are one. Never for [resetFromText]: there the log
  /// already exists, and an id it once tombstoned would delete the text.
  void _seedFromText(
    String text, {
    bool markAsPending = false,
    bool sharedIds = false,
  }) {
    _live = null;
    _liveText = null;
    _runLastId = null;
    final positions = FractionalIndex.spread(text.length);
    final prefix = sharedIds ? 'seed_${_textHash(text)}' : null;
    for (var i = 0; i < text.length; i++) {
      final char = text[i];
      final pos = positions[i];
      final id = prefix != null
          ? '${prefix}_$pos'
          : '${clientId}_${_logicalClock}_$pos';
      _opsById[id] = CharacterOperation(
        id: id,
        clientId: clientId,
        logicalClock: _logicalClock++,
        position: pos,
        character: char,
      );
      if (markAsPending) _pendingOpIds.add(id);
    }
  }

  /// FNV-1a over the text's UTF-16 units: the same on every device. Seeds of
  /// different texts get different ids, so neither overwrites the other's
  /// characters one by one.
  static String _textHash(String text) {
    var hash = 0x811c9dc5;
    for (final unit in text.codeUnits) {
      hash = ((hash ^ unit) * 0x01000193) & 0xffffffff;
    }
    return hash.toRadixString(36);
  }

  void _loadFromOperations(List<CharacterOperation> operations) {
    _live = null;
    _liveText = null;
    var maxClock = -1;
    for (final op in operations) {
      _opsById[op.id] = op;
      if (op.clientId == clientId && op.logicalClock > maxClock) {
        maxClock = op.logicalClock;
      }
    }
    _logicalClock = maxClock + 1;
  }

  CharacterOperation _insertOp({
    required String char,
    required String position,
  }) {
    final id = '${clientId}_${_logicalClock}_$position';
    final op = CharacterOperation(
      id: id,
      clientId: clientId,
      logicalClock: _logicalClock++,
      position: position,
      character: char,
    );
    _opsById[id] = op;
    _pendingOpIds.add(id);
    return op;
  }

  void _tombstone(String id) {
    final existing = _opsById[id];
    if (existing == null || existing.deleted) return;
    final tombstoned = existing.copyWith(deleted: true);
    _opsById[id] = tombstoned;
    _pendingOpIds.add(id);
  }

  List<CharacterOperation> _liveOrderedOps() {
    return _live ??= (_opsById.values.where((op) => !op.deleted).toList()
      ..sort(compareOps));
  }

  String _reconstructText() {
    return _liveText ??= _liveOrderedOps().map((op) => op.character).join();
  }
}

/// Registry of active character-op editing sessions keyed by document.
class CharacterOpRegistry {
  final Map<String, CharacterOpSession> _sessions = {};

  String key(String collection, String documentId) =>
      '${collection}_$documentId';

  CharacterOpSession ensureSession({
    required String collection,
    required String documentId,
    required String clientId,
    String? initialText,
    List<CharacterOperation>? operations,
    bool markSeedsAsPending = false,
  }) {
    final k = key(collection, documentId);
    return _sessions.putIfAbsent(
      k,
      () => CharacterOpSession(
        clientId: clientId,
        initialText: initialText,
        initialOperations: operations,
        seedAsPending: markSeedsAsPending,
      ),
    );
  }

  void loadSession({
    required String collection,
    required String documentId,
    required String clientId,
    required List<CharacterOperation> operations,
  }) {
    final k = key(collection, documentId);
    _sessions[k] = CharacterOpSession(
      clientId: clientId,
      initialOperations: operations,
    );
  }

  CharacterOpSession? session(String collection, String documentId) {
    return _sessions[key(collection, documentId)];
  }

  void recordTextChange({
    required String collection,
    required String documentId,
    required String clientId,
    required String before,
    required String after,
  }) {
    final session = ensureSession(
      collection: collection,
      documentId: documentId,
      clientId: clientId,
      initialText: before,
    );
    session.recordTextChange(before, after);
  }

  List<CharacterOperation> takePendingOps(
    String collection,
    String documentId,
  ) {
    return _sessions[key(collection, documentId)]?.takePendingOps() ?? const [];
  }

  /// Returns operations to the pending set after their upload failed â€” see
  /// [CharacterOpSession.restorePendingOps].
  void restorePendingOps(
    String collection,
    String documentId,
    List<CharacterOperation> operations,
  ) {
    _sessions[key(collection, documentId)]?.restorePendingOps(operations);
  }

  /// See [CharacterOpSession.absorbRemote]. A document with no session has
  /// nothing to fold into; its next session loads the log whole.
  void absorbRemote(
    String collection,
    String documentId,
    List<CharacterOperation> operations,
  ) {
    _sessions[key(collection, documentId)]?.absorbRemote(operations);
  }

  void resetSession({
    required String collection,
    required String documentId,
    required String clientId,
    required String text,
  }) {
    final k = key(collection, documentId);
    _sessions[k] = CharacterOpSession(clientId: clientId, initialText: text);
  }

  void removeSession(String collection, String documentId) {
    _sessions.remove(key(collection, documentId));
  }

  void clear() => _sessions.clear();
}
